-- PQC Readiness Tracker — index refresh 2026-11-27
-- Generated by scripts/build-index-migration.js from the reviewed files in scripts/indices/current/.
-- Single transaction, idempotent (safe to re-run). Never deletes domains or scan history.
begin;

-- 1. Domain corrections --------------------------------------------------------
create temp table _fix (old_domain text primary key, new_domain text not null) on commit drop;
-- 1a. target already tracked: move the index links to it and retire the old row
  select t.id, di.index_id, di.rank, di.year
  from _fix f join domains o on o.domain = f.old_domain
              join domains t on t.domain = f.new_domain
              join domain_indexes di on di.domain_id = o.id
  on conflict (domain_id, index_id) do nothing;
delete from domain_indexes di
  using _fix f, domains o, domains t
  where o.domain = f.old_domain and t.domain = f.new_domain and di.domain_id = o.id;
update domains o
  set active = false,
      notes = concat_ws(E'\n', nullif(o.notes, ''), 'Merged into ' || f.new_domain || ' (2026-11-27)'),
      updated_at = now()
  from _fix f
  where o.domain = f.old_domain and o.active
    and exists (select 1 from domains t where t.domain = f.new_domain);
-- 1b. otherwise rename in place (keeps id, index links and scan history)
update domains d set domain = f.new_domain, updated_at = now()
  from _fix f
  where d.domain = f.old_domain
    and not exists (select 1 from domains t where t.domain = f.new_domain);
update domains set country = 'United States', updated_at = now() where domain = 'ipgphotonics.com';
update domains set company_name = 'DaVita', updated_at = now() where domain = 'davita.com';
update domains set company_name = 'Standard Life', country = 'United Kingdom', updated_at = now() where domain = 'standardlifeplc.com';
update domains set active = false, notes = concat_ws(E'\n', nullif(notes, ''), 'Not an S&P 500 company (bad source data) — deactivated 2026-11-27'), updated_at = now() where domain = 'rapidcreditboosters.com' and active;

-- 2. Indices -------------------------------------------------------------------
on conflict (key) do nothing;

-- 3. Current constituents -------------------------------------------------------
create temp table _member (index_key text, domain text, rank int, company_name text, country text, sector text, primary key (index_key, domain)) on commit drop;
-- new organisations only; existing rows keep their name/country/sector untouched
  select distinct on (domain) domain, company_name, country, sector, true, 'Source: index constituents (Wikipedia/Wikidata, 2026-11-27)'
  from _member order by domain, rank
  on conflict (domain) do nothing;
  select d.id, i.id, m.rank, 2026
  from _member m join domains d on d.domain = m.domain join indexes i on i.key = m.index_key
  on conflict (domain_id, index_id) do update set rank = excluded.rank, year = excluded.year;

-- 4. Companies that left a refreshed index: unlink only (they stay monitored → "Other")
delete from domain_indexes di
  using indexes i
  where di.index_id = i.id
    and i.key in ('sp500', 'ftse100', 'dax', 'cac40', 'ibex35', 'euro-stoxx50')
    and not exists (select 1 from _member m join domains d on d.domain = m.domain
                    where m.index_key = i.key and d.id = di.domain_id);

-- 5. Daily TLS scan for every active domain that has none ------------------------
  select d.id, tt.id, true, true, 'daily', '02:00', (date_trunc('day', now() at time zone 'utc') + interval '1 day 2 hours') at time zone 'utc'
  from domains d
  cross join (select id from test_types where runner_type = 'tls_scan' and active order by created_at limit 1) tt
  where d.active
  on conflict (domain_id, test_type_id) do nothing;

-- 6. Make /stats recompute from the new membership on its next request
delete from stats_cache;

-- 7. Summary (the result shown by the SQL editor) ------------------------------
select 'index: ' || i.name as item, count(di.id)::int as value
  from indexes i left join domain_indexes di on di.index_id = i.id group by i.name
union all select 'active domains', count(*)::int from domains where active
union all select 'inactive domains', count(*)::int from domains where not active
union all select 'active, in no index ("Other")', count(*)::int from domains d
  where d.active and not exists (select 1 from domain_indexes di where di.domain_id = d.id)
union all select 'active without a tls_scan', count(*)::int from domains d
  where d.active and not exists (select 1 from domain_tests t where t.domain_id = d.id)
order by 1;

commit;
